import{I as g,o as p,c,b6 as h,J as e,w as s,j as i,a as t}from"./chunks/framework.BUXTSoD9.js";const d=JSON.parse('{"title":"Mô hình Double Diamond：Làm đúng việc trước, làm đúng cách sau","description":"Bài viết Double Diamond dành cho người mới. Hiểu 4 giai đoạn Discover, Define, Develop, Deliver, tránh bắt tay vào làm nguyên mẫu khi chưa hiểu rõ vấn đề.","frontmatter":{"title":"Mô hình Double Diamond：Làm đúng việc trước, làm đúng cách sau","description":"Bài viết Double Diamond dành cho người mới. Hiểu 4 giai đoạn Discover, Define, Develop, Deliver, tránh bắt tay vào làm nguyên mẫu khi chưa hiểu rõ vấn đề."},"headers":[],"relativePath":"vi-vn/stage-1/appendix-double-diamond/index.md","filePath":"vi-vn/stage-1/appendix-double-diamond/index.md"}'),o={name:"vi-vn/stage-1/appendix-double-diamond/index.md"},b=Object.assign(o,{setup(u){const a="Khoảng <strong>1.5 giờ</strong>";return(r,n)=>{const l=g("ChapterIntroduction");return p(),c("div",null,[n[1]||(n[1]=h('<h1 id="mo-hinh-double-diamond-lam-đung-viec-truoc-lam-đung-cach-sau" tabindex="-1">Mô hình Double Diamond：Làm đúng việc trước, làm đúng cách sau <a class="header-anchor" href="#mo-hinh-double-diamond-lam-đung-viec-truoc-lam-đung-cach-sau" aria-label="Permalink to “Mô hình Double Diamond：Làm đúng việc trước, làm đúng cách sau”">​</a></h1><p><a id="top-dd"></a></p><h2 id="huong-dan-chuong-nay" tabindex="-1">Hướng dẫn chương này <a class="header-anchor" href="#huong-dan-chuong-nay" aria-label="Permalink to “Hướng dẫn chương này”">​</a></h2>',3)),e(l,{duration:a,tags:["Double Diamond","Tư duy thiết kế","Phân tích nhu cầu","Thiết kế giải pháp"],coreOutput:"1 định nghĩa vấn đề rõ ràng hơn và 1 điểm vào xác minh hợp lý hơn",expectedOutput:"Không còn vội vàng vẽ nguyên mẫu ngay từ đầu, mà biết nghĩ rõ vấn đề trước, rồi mới so sánh giải pháp"},{default:s(()=>[...n[0]||(n[0]=[i("p",null,'Rất nhiều người lần đầu làm sản phẩm, cạm bẫy dễ rơi nhất không phải "không đủ nỗ lực", mà là bước vào giải pháp quá nhanh.',-1),i("p",null,"Trong đầu vừa nảy ra một hướng, đã bắt đầu nghĩ trang vẽ thế nào, nút đặt ở đâu, có nên kết nối AI không, có nên làm đăng nhập đăng ký không, nguyên mẫu dùng công cụ gì vẽ. Bận rộn một hồi, mới phát hiện vấn đề cơ bản nhất chưa nghĩ rõ: Người dùng có thực sự có điểm đau này không? Vấn đề này có đáng giải quyết bây giờ không? Bạn tưởng mình đang thúc đẩy dự án, thực ra chỉ đang tăng tốc rất chăm chỉ trên sai hướng.",-1),i("p",null,"Mô hình Double Diamond (Kim cương kép) là để tránh tình huống này.",-1),i("p",null,[t("Lời nhắc có giá trị nhất của nó là: "),i("strong",null,'"Làm đúng việc" và "Làm đúng cách", là hai giai đoạn hoàn toàn khác nhau.'),t(" Nếu bạn chưa hiểu rõ vấn đề, đã vội vàng làm nguyên mẫu, thường chỉ sẽ hoàn thiện hơn trên sai hướng.")],-1)])]),_:1}),n[2]||(n[2]=h(`<div class="info custom-block"><p class="custom-block-title">SOP tối thiểu</p><p><strong>Mục đích</strong>: Sau khi đọc xong, bạn sẽ rõ hơn khi làm sản phẩm lúc nào nên nghĩ vấn đề trước, lúc nào mới nên bắt đầu nghĩ giải pháp và nguyên mẫu, tránh vừa lên đã làm rất nghiêm túc trên sai hướng.</p><p><strong>Hành động</strong>: Theo 4 bước <code>Discover → Define → Develop → Deliver</code> đi xuống, mỗi bước chỉ làm việc nên làm ở giai đoạn hiện tại.</p><p><strong>Kết quả</strong>: Bạn sẽ có một định nghĩa vấn đề rõ ràng hơn, vài giải pháp có thể so sánh, và một phiên bản tối thiểu có thể xác minh.</p><p><strong>Từ khóa chuyển nhanh</strong>: <a href="#dd-what">Double Diamond là gì</a> · <a href="#dd-first">Kim cương đầu tiên</a> · <a href="#dd-ai">AI giúp bạn thế nào</a></p></div><h2 id="ban-se-hoc-đuoc-nhung-noi-dung-sau" tabindex="-1">Bạn sẽ học được những nội dung sau <a class="header-anchor" href="#ban-se-hoc-đuoc-nhung-noi-dung-sau" aria-label="Permalink to “Bạn sẽ học được những nội dung sau”">​</a></h2><ol><li>Mô hình Double Diamond là gì, tại sao nó phù hợp cho người mới làm sản phẩm</li><li>Bốn giai đoạn Discover, Define, Develop, Deliver lần lượt đang làm gì</li><li>Làm thế nào phân biệt &quot;bây giờ nên tiếp tục phân tán&quot; hay &quot;bây giờ nên bắt đầu tập trung&quot;</li><li>Cách dùng mô hình Double Diamond trong sản phẩm AI, thiết kế nguyên mẫu và xác minh nhu cầu</li></ol><p><a id="dd-what"></a></p><h2 id="_1-mo-hinh-double-diamond-thuc-chat-la-gi" tabindex="-1"><a href="#top-dd">1. Mô hình Double Diamond thực chất là gì</a> <a class="header-anchor" href="#_1-mo-hinh-double-diamond-thuc-chat-la-gi" aria-label="Permalink to “1. Mô hình Double Diamond thực chất là gì”">​</a></h2><p>Mô hình Double Diamond là một quy trình thiết kế kinh điển do <strong>Design Council</strong> Anh quốc phổ biến. Nó vẽ một quy trình thiết kế và đổi mới hoàn chỉnh thành hai hình kim cương liên tiếp.</p><p>Lý do là &quot;kim cương&quot;, là vì mỗi kim cương đều bao gồm hai động tác trái ngược nhưng đều quan trọng:</p><ul><li><strong>Phân tán</strong>: Trước mở rộng tầm nhìn, xem nhiều khả năng hơn</li><li><strong>Tập trung</strong>: Rồi thu hẹp phạm vi, đưa ra đánh giá và lựa chọn</li></ul><p>Toàn bộ quá trình gồm 4 bước:</p><ol><li><strong>Discover</strong>: Hiểu rộng về người dùng, vấn đề, môi trường và thị trường</li><li><strong>Define</strong>: Từ lượng lớn thông tin, tinh lọc ra vấn đề cốt lõi thực sự đáng giải quyết</li><li><strong>Develop</strong>: Phân tán nhiều giải pháp xoay quanh vấn đề cốt lõi</li><li><strong>Deliver</strong>: Sàng lọc, nguyên mẫu, kiểm thử và giao phó giải pháp phù hợp hơn</li></ol><p>Nếu nén 4 bước này thành một câu dễ nhớ nhất, thì là:</p><ul><li><strong>Kim cương đầu tiên</strong>: Trước làm rõ phải giải quyết vấn đề gì</li><li><strong>Kim cương thứ hai</strong>: Rồi quyết định dùng giải pháp gì để giải quyết nó</li></ul><p>Cũng chính là câu bạn nói rất chính xác:</p><ul><li><strong>Kim cương đầu tiên: Làm đúng việc</strong></li><li><strong>Kim cương thứ hai: Làm đúng cách</strong></li></ul><h2 id="_2-tai-sao-mo-hinh-double-diamond-đac-biet-phu-hop-cho-nguoi-moi" tabindex="-1">2. Tại sao mô hình Double Diamond đặc biệt phù hợp cho người mới <a class="header-anchor" href="#_2-tai-sao-mo-hinh-double-diamond-đac-biet-phu-hop-cho-nguoi-moi" aria-label="Permalink to “2. Tại sao mô hình Double Diamond đặc biệt phù hợp cho người mới”">​</a></h2><p>Nhịp điệu phổ biến nhất khi người mới làm sản phẩm, thường là như thế này:</p><ul><li>Nghĩ ra một ý tưởng</li><li>Thấy hướng này rất ngầu</li><li>Ngay lập tức bắt đầu vẽ nguyên mẫu</li><li>Làm làm thấy chức năng ngày càng nhiều</li><li>Cuối cùng không biết mình đang giải quyết vấn đề gì</li></ul><p>Giá trị của mô hình Double Diamond, không phải làm cho quy trình phức tạp, mà là <strong>ép bạn tách &quot;hiểu vấn đề&quot; và &quot;thiết kế giải pháp&quot; ra</strong>.</p><p>Điều này nghe rất bình thường, nhưng thực tế rất quan trọng. Vì rất nhiều sản phẩm thất bại, không phải thực hiện không nghiêm túc, mà là:</p><ul><li>Chọn sai vấn đề</li><li>Hiểu sai người dùng</li><li>Khóa giải pháp quá sớm</li><li>Dành nhiều thời gian mài giũa chi tiết, lại không xác minh hướng đi</li></ul><p>Mô hình Double Diamond chính là không ngừng nhắc bạn:</p><ul><li>Đừng vì ý tưởng thuận tay, thì mặc nhiên vấn đề đã thành lập</li><li>Đừng vì giải pháp có thể làm ra, thì mặc nhiên nó đáng làm</li><li>Đừng vì nguyên mẫu trông hoàn chỉnh, thì mặc nhiên người dùng thực sự cần</li></ul><p><a id="dd-first"></a></p><h2 id="_3-kim-cuong-đau-tien-lam-đung-viec" tabindex="-1"><a href="#top-dd">3. Kim cương đầu tiên: Làm đúng việc</a> <a class="header-anchor" href="#_3-kim-cuong-đau-tien-lam-đung-viec" aria-label="Permalink to “3. Kim cương đầu tiên: Làm đúng việc”">​</a></h2><p>Kim cương đầu tiên tập trung vào <strong>bản thân vấn đề</strong>, chứ không phải giải pháp.</p><p>Bạn có thể hiểu nó thành một câu: <strong>Trước đừng vội làm, trước làm rõ có đáng làm hay không.</strong></p><h3 id="_3-1-discover-truoc-mo-rong-khong-gian-van-đe" tabindex="-1">3.1 Discover: Trước mở rộng không gian vấn đề <a class="header-anchor" href="#_3-1-discover-truoc-mo-rong-khong-gian-van-đe" aria-label="Permalink to “3.1 Discover: Trước mở rộng không gian vấn đề”">​</a></h3><p>Nhiệm vụ cốt lõi của giai đoạn Discover, là <strong>nghiên cứu rộng, chứ không phải nhanh chóng kết luận</strong>.</p><p>Bước này thường làm những việc bao gồm:</p><ul><li>Xem người dùng làm thế nào trong kịch bản thực tế</li><li>Phỏng vấn người dùng tiềm năng, hiểu lần gần nhất họ gặp vấn đề là khi nào</li><li>Quan sát họ hiện đang khắc phục tạm thế nào</li><li>Xem sản phẩm cạnh tranh và giải pháp thay thế đang xử lý thế nào</li><li>Thu thập thông tin thị trường, quy trình, ràng buộc, upstream và downstream</li></ul><p>Rất nhiều người sẽ nhầm tưởng Discover là &quot;xem thêm tài liệu&quot;. Thực ra then chốt hơn là: <strong>Bạn cần hiểu con người và kịch bản, chứ không chỉ tìm một đống thông tin.</strong></p><p>Ví dụ bạn muốn làm một công cụ &quot;AI giúp sắp xếp biên bản cuộc họp&quot;, ở giai đoạn Discover nên quan tâm hơn là:</p><ul><li>Người dùng sau cuộc họp rốt cuộc đau nhất ở đâu</li><li>Là ghi chép khó, hay sắp xếp khó, hay đồng bộ khó</li><li>Hiện họ tự viết, nhờ thực tập sinh viết, nghe lại ghi âm, hay đơn giản không sắp xếp</li><li>Kịch bản cuộc họp nào cần biên bản nhất, kịch bản nào căn bản không cần</li></ul><p>Mục tiêu quan trọng nhất của bước này không phải được câu trả lời, mà là <strong>đừng quá sớm tưởng mình đã biết câu trả lời.</strong></p><h3 id="_3-2-define-tu-mot-đong-thong-tin-tinh-loc-ra-van-đe-cot-loi" tabindex="-1">3.2 Define: Từ một đống thông tin tinh lọc ra vấn đề cốt lõi <a class="header-anchor" href="#_3-2-define-tu-mot-đong-thong-tin-tinh-loc-ra-van-đe-cot-loi" aria-label="Permalink to “3.2 Define: Từ một đống thông tin tinh lọc ra vấn đề cốt lõi”">​</a></h3><p>Nếu Discover là mở rộng tầm nhìn, thì Define là bắt đầu thu hẹp.</p><p>Những gì Define cần làm, không phải giữ lại tất cả quan sát, mà là hỏi:</p><ul><li>Vấn đề thực sự đáng ưu tiên giải quyết là cái nào</li><li>Vấn đề nào thường xuất hiện nhất, đau nhất, có giá trị nhất</li><li>Phiên bản đầu tiên của chúng ta thực sự chỉ tập trung vào kịch bản nào</li></ul><p>Cốt lõi của bước này, là thu một chủ đề rộng thành một định nghĩa vấn đề rõ ràng.</p><p>Ví dụ ban đầu bạn nói:</p><blockquote><p>Tôi muốn làm một công cụ AI nâng cao hiệu quả họp.</p></blockquote><p>Đến giai đoạn Define, cách diễn đạt tốt hơn có thể trở thành:</p><blockquote><p>Chúng ta giải quyết trước vấn đề: sau cuộc họp điều phối 30 đến 60 phút của nhóm dự án, không thể xuất biên bản kèm việc cần làm, người phụ trách và thời hạn trong 10 phút.</p></blockquote><p>Lúc này vấn đề bắt đầu rõ hơn:</p><ul><li>Người dùng là ai</li><li>Kịch bản là gì</li><li>Điểm nghẽn là gì</li><li>Tiêu chuẩn thành công là gì</li></ul><p>Bản chất của Define, là <strong>từ &quot;nhiều vấn đề&quot; tập trung về &quot;lần này giải quyết vấn đề nào trước&quot;.</strong></p><h2 id="_4-kim-cuong-thu-hai-lam-đung-cach" tabindex="-1">4. Kim cương thứ hai: Làm đúng cách <a class="header-anchor" href="#_4-kim-cuong-thu-hai-lam-đung-cach" aria-label="Permalink to “4. Kim cương thứ hai: Làm đúng cách”">​</a></h2><p>Khi bạn hoàn thành kim cương đầu tiên, mới thực sự phù hợp để bước vào kim cương thứ hai. Vì lúc này bạn giải quyết không phải một hướng mơ hồ, mà là một vấn đề cụ thể đã được tập trung.</p><h3 id="_4-1-develop-phan-tan-giai-phap-xoay-quanh-van-đe-cot-loi" tabindex="-1">4.1 Develop: Phân tán giải pháp xoay quanh vấn đề cốt lõi <a class="header-anchor" href="#_4-1-develop-phan-tan-giai-phap-xoay-quanh-van-đe-cot-loi" aria-label="Permalink to “4.1 Develop: Phân tán giải pháp xoay quanh vấn đề cốt lõi”">​</a></h3><p>Trọng tâm giai đoạn Develop, là <strong>xoay quanh cùng một vấn đề, khám phá nhiều giải pháp khả thi.</strong></p><p>Lưu ý, phân tán ở đây và giai đoạn Discover không giống nhau.</p><ul><li>Phân tán của Discover, đang khám phá không gian vấn đề</li><li>Phân tán của Develop, đang khám phá không gian giải pháp</li></ul><p>Ví dụ vẫn là biên bản cuộc họp, đến giai đoạn Develop, bạn có thể bắt đầu nghĩ:</p><ul><li>Làm công cụ web, hay plugin cuộc họp</li><li>Là upload ghi âm rồi xử lý, hay ghi nhận thời gian thực</li><li>Chỉ làm tóm tắt, hay tập trung trích xuất việc cần làm</li><li>Nhấn mạnh hiệu quả cá nhân, hay nhấn mạnh đồng bộ nhóm</li><li>Cho người dùng tự do chỉnh sửa, hay trực tiếp xuất template có cấu trúc</li></ul><p>Bước này rất phù hợp brainstorm, cũng rất phù hợp cùng nhóm kéo giải pháp ra.</p><p>Nhưng ở đây có một tiền đề: <strong>Tất cả giải pháp đều phải phục vụ cùng một vấn đề đã được định nghĩa.</strong> Nếu vấn đề chưa được định nghĩa rõ, Develop rất dễ lại trở thành chức năng bay tứ tung.</p><h3 id="_4-2-deliver-chon-giai-phap-lam-nguyen-mau-kiem-thu-va-giao-pho" tabindex="-1">4.2 Deliver: Chọn giải pháp, làm nguyên mẫu, kiểm thử và giao phó <a class="header-anchor" href="#_4-2-deliver-chon-giai-phap-lam-nguyen-mau-kiem-thu-va-giao-pho" aria-label="Permalink to “4.2 Deliver: Chọn giải pháp, làm nguyên mẫu, kiểm thử và giao phó”">​</a></h3><p>Giai đoạn Deliver là giai đoạn tập trung trong kim cương thứ hai.</p><p>Lúc này bạn cần làm không phải tiếp tục nghĩ nhiều hơn, mà bắt đầu đánh giá:</p><ul><li>Giải pháp nào phù hợp nhất với giai đoạn hiện tại</li><li>Phiên bản nào nhỏ nhất nhưng hữu dụng nhất</li><li>Chức năng nào phải làm trước, chức năng nào có thể làm sau</li><li>Làm nguyên mẫu, kiểm thử và xác minh quy mô nhỏ thế nào</li></ul><p>Rất nhiều người tưởng Deliver đồng nghĩa với &quot;lên mạng&quot;. Thực ra ý nghĩa chính xác hơn của nó là: <strong>Biến một giải pháp thành thứ có thể kiểm thử, có thể xác minh, có thể lặp lại.</strong></p><p>Nó có thể là:</p><ul><li>Một flowchart độ fidelity thấp</li><li>Một nguyên mẫu Figma</li><li>Một MVP có thể chạy</li><li>Một lần kiểm thử người dùng quy mô nhỏ</li><li>Một phiên bản lặp lại sau phản hồi thực tế</li></ul><p>Trọng tâm của Deliver không phải &quot;giao phó hoàn hảo&quot;, mà là <strong>càng sớm càng tốt đặt giải pháp vào môi trường thực tế để xác minh.</strong></p><h2 id="_5-mot-bang-đoi-chieu-de-nho-nhat" tabindex="-1">5. Một bảng đối chiếu dễ nhớ nhất <a class="header-anchor" href="#_5-mot-bang-đoi-chieu-de-nho-nhat" aria-label="Permalink to “5. Một bảng đối chiếu dễ nhớ nhất”">​</a></h2><p>Nếu bạn luôn không phân biệt được bốn giai đoạn, có thể trực tiếp ghi phiên bản dưới đây:</p><table tabindex="0"><thead><tr><th>Giai đoạn</th><th>Bạn đang làm gì</th><th>Từ khóa</th><th>Sản xuất phổ biến</th></tr></thead><tbody><tr><td>Discover</td><td>Hiểu vấn đề</td><td>Nghiên cứu, quan sát, phỏng vấn, thu thập thông tin</td><td>Insight người dùng, ghi chú kịch bản, danh sách vấn đề</td></tr><tr><td>Define</td><td>Định nghĩa vấn đề</td><td>Tinh lọc, tập trung, lựa chọn, viết lại vấn đề</td><td>Định nghĩa vấn đề, ưu tiên, điểm vào MVP</td></tr><tr><td>Develop</td><td>Khám phá giải pháp</td><td>Brainstorm, so sánh, đồng sáng tạo, hình dung nguyên mẫu</td><td>Danh sách giải pháp, sketch flowchart, hướng nguyên mẫu</td></tr><tr><td>Deliver</td><td>Xác minh giải pháp</td><td>Nguyên mẫu, kiểm thử, lặp lại, giao phó</td><td>Nguyên mẫu, phản hồi kiểm thử, phiên bản tối ưu</td></tr></tbody></table><p>Nén thêm một chút, thì là:</p><ul><li><strong>Discover / Define</strong>: Giải quyết &quot;làm đúng việc&quot;</li><li><strong>Develop / Deliver</strong>: Giải quyết &quot;làm đúng cách&quot;</li></ul><h2 id="_6-sai-lam-pho-bien-nhat-voi-mo-hinh-double-diamond" tabindex="-1">6. Sai lầm phổ biến nhất với mô hình Double Diamond <a class="header-anchor" href="#_6-sai-lam-pho-bien-nhat-voi-mo-hinh-double-diamond" aria-label="Permalink to “6. Sai lầm phổ biến nhất với mô hình Double Diamond”">​</a></h2><h3 id="_6-1-chua-discover-đa-truc-tiep-deliver" tabindex="-1">6.1 Chưa Discover, đã trực tiếp Deliver <a class="header-anchor" href="#_6-1-chua-discover-đa-truc-tiep-deliver" aria-label="Permalink to “6.1 Chưa Discover, đã trực tiếp Deliver”">​</a></h3><p>Đây là loại phổ biến nhất. Rất nhiều người vừa có ý tưởng đã vẽ nguyên mẫu, viết PRD, kết nối mô hình, làm trang.</p><p>Vấn đề không phải bạn làm không nghiêm túc, mà có thể bạn căn bản chưa xác nhận vấn đề có đáng giải quyết hay không.</p><h3 id="_6-2-discover-rat-lau-nhung-luon-khong-define" tabindex="-1">6.2 Discover rất lâu, nhưng luôn không Define <a class="header-anchor" href="#_6-2-discover-rat-lau-nhung-luon-khong-define" aria-label="Permalink to “6.2 Discover rất lâu, nhưng luôn không Define”">​</a></h3><p>Một cực đoan khác là luôn nghiên cứu, luôn xem tài liệu, luôn phỏng vấn, lại luôn không dám tập trung.</p><p>Double Diamond không phải để bạn phân tán vô hạn, mà nhắc bạn: Sau khi phân tán phải bước vào đánh giá và lựa chọn.</p><h3 id="_6-3-sau-khi-define-lai-len-sua-van-đe" tabindex="-1">6.3 Sau khi Define, lại lén sửa vấn đề <a class="header-anchor" href="#_6-3-sau-khi-define-lai-len-sua-van-đe" aria-label="Permalink to “6.3 Sau khi Define, lại lén sửa vấn đề”">​</a></h3><p>Rất nhiều nhóm sẽ ở giai đoạn Develop vì một giải pháp dễ làm hơn, nên ngược lại sửa định nghĩa vấn đề, cho nó phù hợp với giải pháp hiện có.</p><p>Điều này rất nguy hiểm. Vì có thể bạn không đang giải quyết vấn đề, mà đang tìm lý do cho giải pháp bạn thích.</p><h3 id="_6-4-hieu-sai-deliver-thanh-len-mang-đai-toan" tabindex="-1">6.4 Hiểu sai Deliver thành &quot;lên mạng đại toàn&quot; <a class="header-anchor" href="#_6-4-hieu-sai-deliver-thanh-len-mang-đai-toan" aria-label="Permalink to “6.4 Hiểu sai Deliver thành &quot;lên mạng đại toàn&quot;”">​</a></h3><p>Deliver không phải nói phải làm xong sản phẩm hoàn chỉnh mới tính kết thúc. Rất nhiều lúc, một nguyên mẫu có thể kiểm thử, một vòng dùng thử người dùng thực tế, đã là một deliver rất tốt.</p><h2 id="_7-trong-san-pham-ai-dung-mo-hinh-double-diamond-the-nao" tabindex="-1">7. Trong sản phẩm AI, dùng mô hình Double Diamond thế nào <a class="header-anchor" href="#_7-trong-san-pham-ai-dung-mo-hinh-double-diamond-the-nao" aria-label="Permalink to “7. Trong sản phẩm AI, dùng mô hình Double Diamond thế nào”">​</a></h2><p>Sản phẩm AI đặc biệt dễ rơi vào bẫy &quot;khả năng đi trước&quot;, vì khả năng mô hình trông quá hấp dẫn. Bạn sẽ rất muốn trực tiếp đi nghĩ:</p><ul><li>Có nên kết nối đa mô thức không</li><li>Có nên làm Agent không</li><li>Có nên thêm workflow không</li><li>Có nên kết nối giọng nói, hình ảnh, tìm kiếm mạng không</li></ul><p>Nhưng mô hình Double Diamond sẽ ép bạn hỏi trước:</p><ul><li>Người dùng rốt cuộc bị kẹt ở khâu nào</li><li>Điểm nghẽn này có phải bắt buộc dùng AI không</li><li>Nếu không dùng AI, phương pháp hiện tại rốt cuộc kém nhất ở đâu</li><li>Sau khi thêm AI vào, tiến triển cốt lõi nhất là gì</li></ul><p>Điều này giúp bạn tránh một tình huống phổ biến: <strong>Khả năng rất mạnh, giá trị rất yếu.</strong></p><p>Một trình tự thực dụng là:</p><ol><li>Ở giai đoạn Discover quan sát người dùng hiện đang xử lý nhiệm vụ thế nào</li><li>Ở giai đoạn Define viết một kịch bản đau nhất thành một định nghĩa vấn đề rõ ràng</li><li>Ở giai đoạn Develop rồi đi so sánh khả năng AI nào phù hợp nhất phục vụ vấn đề này</li><li>Ở giai đoạn Deliver làm một phiên bản tối thiểu, để người dùng thực tế kiểm thử</li></ol><h2 id="_8-template-double-diamond-co-the-ap-dung-truc-tiep" tabindex="-1">8. Template Double Diamond có thể áp dụng trực tiếp <a class="header-anchor" href="#_8-template-double-diamond-co-the-ap-dung-truc-tiep" aria-label="Permalink to “8. Template Double Diamond có thể áp dụng trực tiếp”">​</a></h2><p>Nếu bạn đang làm sản phẩm của mình, có thể trước viết theo trình tự dưới đây:</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>Người dùng tôi quan sát là ai?</li><li>Lần gần nhất họ gặp vấn đề này là khi nào?</li><li>Hiện họ giải quyết thế nào?</li><li>Nơi họ phiền nhất, chậm nhất, không yên tâm nhất là gì?</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>Trong đống vấn đề này, cái nào đáng ưu tiên giải quyết nhất?</li><li>Kịch bản nào tần suất cao nhất, hoặc quan trọng nhất?</li><li>Phiên bản đầu tiên của chúng ta phục vụ ai trước, giải quyết cái gì trước?</li><li>Sau khi giải quyết thành công, trạng thái người dùng sẽ thay đổi thế nào?</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>Đối với vấn đề này, có những giải pháp khả thi nào?</li><li>Giải pháp nào nhẹ nhất, nhanh nhất, dễ xác minh nhất?</li><li>Cái nào phải làm, cái nào làm sau?</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>Chúng ta nhỏ nhất có thể giao phó gì để xác minh hướng này?</li><li>Là flowchart, nguyên mẫu, hay MVP?</li><li>Cần tìm ai kiểm thử?</li><li>Sau khi kiểm thử đánh giá thế nào: tiếp tục, sửa đổi hay dừng lại?</li></ul><h2 id="_9-mot-vi-du-nguoi-moi-cung-co-the-hieu" tabindex="-1">9. Một ví dụ người mới cũng có thể hiểu <a class="header-anchor" href="#_9-mot-vi-du-nguoi-moi-cung-co-the-hieu" aria-label="Permalink to “9. Một ví dụ người mới cũng có thể hiểu”">​</a></h2><p>Giả sử bạn muốn làm một công cụ AI &quot;giúp sinh viên chuẩn bị CV xin việc&quot;.</p><p>Rất nhiều người vừa bắt đầu sẽ trực tiếp bước vào kim cương thứ hai, bắt đầu nghĩ:</p><ul><li>Có nên làm làm đẹp một lần không</li><li>Có nên sửa viết thông minh không</li><li>Có nên tự động khớp JD không</li><li>Có nên tạo tự giới thiệu không</li></ul><p>Nhưng theo mô hình Double Diamond, quá trình tốt hơn sẽ là như thế này:</p><h3 id="kim-cuong-đau-tien" tabindex="-1">Kim cương đầu tiên <a class="header-anchor" href="#kim-cuong-đau-tien" aria-label="Permalink to “Kim cương đầu tiên”">​</a></h3><p><strong>Discover</strong></p><ul><li>Đi hỏi sinh viên năm cuối lần gần nhất sửa CV là khi nào</li><li>Xem họ sửa từ CV cũ thành phiên bản mới thế nào</li><li>Hiểu họ phiền nhất là &quot;không biết viết&quot;, &quot;không biết sửa&quot;, hay &quot;không biết đánh giá tốt chưa&quot;</li></ul><p><strong>Define</strong></p><ul><li>Cuối cùng tập trung thành một vấn đề cụ thể hơn:</li><li>Không phải &quot;sinh viên không biết làm CV&quot;</li><li>Mà là &quot;sinh viên lần đầu nộp thực tập, rất khó sửa kinh nghiệm hiện có thành diễn đạt phù hợp với vị trí, do đó trì hoãn nộp hồ sơ&quot;</li></ul><h3 id="kim-cuong-thu-hai" tabindex="-1">Kim cương thứ hai <a class="header-anchor" href="#kim-cuong-thu-hai" aria-label="Permalink to “Kim cương thứ hai”">​</a></h3><p><strong>Develop</strong></p><ul><li>Nghĩ vài giải pháp: Thư viện template, AI sửa viết, đối chiếu vị trí, đánh giá CV, tham khảo case</li></ul><p><strong>Deliver</strong></p><ul><li>Phiên bản đầu tiên chỉ làm &quot;sửa viết bullet points kinh nghiệm dựa trên mô tả vị trí&quot;</li><li>Cho 5 sinh viên dùng thử, xem họ có nộp nhanh hơn CV phiên bản đầu tiên không</li></ul><p>Bạn sẽ phát hiện, một khi kim cương đầu tiên làm vững, kim cương thứ hai sẽ rõ ràng hơn nhiều.</p><h2 id="_10-tom-tat" tabindex="-1">10. Tóm tắt <a class="header-anchor" href="#_10-tom-tat" aria-label="Permalink to “10. Tóm tắt”">​</a></h2><p>Điểm mạnh nhất của mô hình Double Diamond, là nó giúp bạn chia một đống hỗn loạn thành bốn động tác rõ ràng hơn:</p><ul><li>Trước phân tán hiểu vấn đề</li><li>Rồi tập trung định nghĩa vấn đề</li><li>Rồi phân tán khám phá giải pháp</li><li>Cuối cùng tập trung giao phó giải pháp</li></ul><p>Nó không phải làm bạn chậm lại, mà giúp bạn <strong>đi ít hơn rất nhiều con đường tưởng bận rộn nhưng thực ra sai hướng.</strong></p><p>Đặc biệt trong thời đại AI, làm ra thứ ngày càng nhanh, mô hình Double Diamond lại càng quan trọng hơn. Vì khi &quot;làm ra&quot; ngày càng dễ, năng lực thực sự khan hiếm sẽ trở thành: <strong>Bạn có đang giải quyết một vấn đề đáng giải quyết hay không, và bạn có dùng cách phù hợp để giải quyết nó hay không.</strong></p><p>Ghi nhớ câu này là đủ:</p><p><strong>Trước làm đúng việc, rồi làm đúng cách.</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-cach-dung-ai-giup-ban-chay-quy-trinh-double-diamond" tabindex="-1"><a href="#top-dd">11. Cách dùng AI giúp bạn chạy quy trình Double Diamond</a> <a class="header-anchor" href="#_11-cach-dung-ai-giup-ban-chay-quy-trinh-double-diamond" aria-label="Permalink to “11. Cách dùng AI giúp bạn chạy quy trình Double Diamond”">​</a></h2><p>Bản thân mô hình Double Diamond không phải công cụ AI, nhưng AI rất phù hợp đóng vai &quot;bộ tăng tốc&quot; trong bốn giai đoạn. Điểm mấu chốt không phải để AI thay bạn quyết định, mà là để nó giúp bạn mở rộng tầm nhìn, sắp xếp thông tin, so sánh giải pháp và tạo tài liệu xác minh.</p><h3 id="_11-1-o-giai-đoan-discover-dung-ai-lam-truoc-mot-vong-lot-thong-tin" tabindex="-1">11.1 Ở giai đoạn Discover, dùng AI làm trước một vòng lót thông tin <a class="header-anchor" href="#_11-1-o-giai-đoan-discover-dung-ai-lam-truoc-mot-vong-lot-thong-tin" aria-label="Permalink to “11.1 Ở giai đoạn Discover, dùng AI làm trước một vòng lót thông tin”">​</a></h3><p>Trước khi phỏng vấn và nghiên cứu chính thức, bạn có thể để AI giúp bạn làm quét vấn đề nhẹ nhàng, ví dụ:</p><ul><li>Trên thị trường có giải pháp thay thế phổ biến nào</li><li>Người dùng trong cộng đồng công khai thường phàn nàn điều gì nhất</li><li>Vấn đề này thường gặp ở kịch bản và nhóm người nào</li><li>Sản phẩm hiện có thường bỏ qua điều gì</li></ul><p>Bước này không thể thay thế nghiên cứu thực tế, nhưng rất phù hợp giúp bạn nhanh chóng xây bản đồ vấn đề.</p><p>Một input rất đơn giản có thể là:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tôi muốn làm một công cụ giúp sinh viên sửa CV.</span></span>
<span class="line"><span>Bạn trước đừng giúp tôi nghĩ chức năng, trước giúp tôi xem mọi người thường gặp rắc rối gì nhất trên vấn đề này.</span></span></code></pre></div><p>AI có thể xuất:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Bản đồ vấn đề ban đầu:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Không biết nên viết kinh nghiệm gì</span></span>
<span class="line"><span>2. Không biết sửa cho phù hợp với vị trí thế nào</span></span>
<span class="line"><span>3. Sửa nhiều phiên bản vẫn không chắc đã đủ tốt</span></span>
<span class="line"><span>4. Cần người khác giúp xem, nhưng không tiện phiền người ta mãi</span></span>
<span class="line"><span>5. Vì không chắc chắn, nên cứ kéo dài không nộp</span></span></code></pre></div><p>Tác dụng của loại output này không phải thay bạn kết luận, mà giúp bạn nhanh bước vào Discover.</p><h3 id="_11-2-o-giai-đoan-define-đe-ai-giup-ban-tap-trung-đinh-nghia-van-đe" tabindex="-1">11.2 Ở giai đoạn Define, để AI giúp bạn tập trung định nghĩa vấn đề <a class="header-anchor" href="#_11-2-o-giai-đoan-define-đe-ai-giup-ban-tap-trung-đinh-nghia-van-đe" aria-label="Permalink to “11.2 Ở giai đoạn Define, để AI giúp bạn tập trung định nghĩa vấn đề”">​</a></h3><p>Rất nhiều người sau khi thu thập một đống tài liệu, khó nhất là nén vấn đề thành một câu thực sự rõ ràng. Bạn có thể giao ghi chú nghiên cứu cho AI, để nó giúp bạn nén thành vài định nghĩa vấn đề ứng viên:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Dưới đây là phản hồi người dùng và ghi chú nghiên cứu tôi thu thập được ở giai đoạn Discover:</span></span>
<span class="line"><span>[Dán nội dung]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Xin giúp tôi làm ba việc:</span></span>
<span class="line"><span>1. Tổng hợp mô hình vấn đề xuất hiện thường xuyên nhất</span></span>
<span class="line"><span>2. Theo tần suất vấn đề, mức độ đau và tính khả thi xác minh, sắp xếp ra 3 vấn đề đáng ưu tiên giải quyết</span></span>
<span class="line"><span>3. Viết mỗi vấn đề thành một định nghĩa vấn đề cụ thể</span></span></code></pre></div><p>Như vậy bạn sẽ dễ bước vào Define hơn, thay vì luôn dừng ở trạng thái &quot;vấn đề nhiều quá&quot;.</p><p>Bạn thậm chí có thể viết input rất đơn giản:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tôi hiện thu thập được các vấn đề:</span></span>
<span class="line"><span>1. Mọi người không biết CV viết gì</span></span>
<span class="line"><span>2. Mọi người không biết sửa thế nào</span></span>
<span class="line"><span>3. Mọi người luôn cảm thấy chưa sửa xong, không dám nộp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bạn giúp tôi xem, phiên bản đầu tiên phù hợp nhất giải quyết vấn đề nào trước.</span></span></code></pre></div><p>AI có thể xuất:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Đề xuất vấn đề đáng ưu tiên giải quyết:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;Sinh viên lần đầu nộp thực tập, không chắc CV đã đạt mức có thể nộp chưa, do đó sẽ sửa lặp đi lặp lại và trì hoãn nộp hồ sơ.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Lý do:</span></span>
<span class="line"><span>1. Vấn đề này cụ thể hơn</span></span>
<span class="line"><span>2. Nó có thể giải thích hành vi trì hoãn</span></span>
<span class="line"><span>3. Dễ thiết kế một phiên bản nhỏ để xác minh hơn</span></span></code></pre></div><p>Loại output này rất hữu ích, vì nó giúp bạn từ đống vấn đề mơ hồ tập trung ra một định nghĩa gần với điểm khởi đầu MVP hơn.</p><h3 id="_11-3-o-giai-đoan-develop-dung-ai-phan-tan-nhieu-giai-phap" tabindex="-1">11.3 Ở giai đoạn Develop, dùng AI phân tán nhiều giải pháp <a class="header-anchor" href="#_11-3-o-giai-đoan-develop-dung-ai-phan-tan-nhieu-giai-phap" aria-label="Permalink to “11.3 Ở giai đoạn Develop, dùng AI phân tán nhiều giải pháp”">​</a></h3><p>Rất nhiều người vừa định nghĩa vấn đề xong, chỉ chăm chăm vào giải pháp đầu tiên nghĩ ra. AI ở bước này rất phù hợp giúp bạn ép phân tán:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tôi đã định nghĩa một vấn đề cốt lõi: [Định nghĩa vấn đề của bạn]</span></span>
<span class="line"><span>Xin đừng trực tiếp cho tôi một câu trả lời cuối cùng, mà từ các góc độ sau mỗi loại đề xuất 2-3 hướng giải quyết:</span></span>
<span class="line"><span>1. MVP nhẹ nhất</span></span>
<span class="line"><span>2. Giải pháp phù hợp nhất để xác minh nhu cầu</span></span>
<span class="line"><span>3. Giải pháp phù hợp nhất để nâng cao trải nghiệm</span></span>
<span class="line"><span>4. Giải pháp không phụ thuộc AI</span></span>
<span class="line"><span>5. Giải pháp phụ thuộc AI</span></span>
<span class="line"><span>Cuối cùng xin so sánh ưu điểm, rủi ro và chi phí xác minh của mỗi giải pháp.</span></span></code></pre></div><p>Như vậy bạn sẽ không quá sớm bị trói vào một giải pháp duy nhất.</p><p>Một input đơn giản:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Định nghĩa vấn đề hiện tại của tôi là:</span></span>
<span class="line"><span>&quot;Sinh viên không chắc CV đã có thể nộp chưa, nên cứ kéo dài không nộp.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Xin giúp tôi nghĩ 4 giải pháp khác nhau, đừng chỉ cho tôi một.</span></span></code></pre></div><p>AI có thể xuất:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Giải pháp 1: Danh sách kiểm tra CV có thể nộp</span></span>
<span class="line"><span>Giải pháp 2: Sửa viết dựa trên mô tả vị trí</span></span>
<span class="line"><span>Giải pháp 3: Người dùng upload CV rồi đưa ra cảnh báo rủi ro</span></span>
<span class="line"><span>Giải pháp 4: Cung cấp đối chiếu case xuất sắc, giúp người dùng đánh giá khoảng cách</span></span></code></pre></div><p>Lúc này bạn dễ bước vào &quot;so sánh giải pháp&quot; hơn, thay vì vừa lên chỉ chăm chăm để AI sửa viết một hướng.</p><h3 id="_11-4-o-giai-đoan-deliver-dung-ai-giup-ban-tao-van-ban-nguyen-mau-va-tai-lieu-kiem-thu" tabindex="-1">11.4 Ở giai đoạn Deliver, dùng AI giúp bạn tạo văn bản nguyên mẫu và tài liệu kiểm thử <a class="header-anchor" href="#_11-4-o-giai-đoan-deliver-dung-ai-giup-ban-tao-van-ban-nguyen-mau-va-tai-lieu-kiem-thu" aria-label="Permalink to “11.4 Ở giai đoạn Deliver, dùng AI giúp bạn tạo văn bản nguyên mẫu và tài liệu kiểm thử”">​</a></h3><p>Khi bạn bước vào giai đoạn Deliver, AI rất phù hợp giúp bạn tăng tốc các công việc này:</p><ul><li>Tạo văn bản trang trong nguyên mẫu độ fidelity thấp</li><li>Sắp xếp script kiểm thử người dùng</li><li>Tạo nhiều phiên bản tiêu đề, nút bấm, mô tả có thể so sánh</li><li>Sắp xếp phản hồi và danh sách vấn đề sau kiểm thử</li></ul><p>Ví dụ bạn có thể để AI giúp bạn tạo một script kiểm thử người dùng 20 phút, hoặc giúp bạn gom 5 phản hồi người dùng thành căn cứ đánh giá &quot;tiếp tục làm / sửa hướng / tạm dừng&quot;.</p><p>Ví dụ một input tối thiểu:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tôi đã làm một nguyên mẫu rất đơn giản:</span></span>
<span class="line"><span>Người dùng upload CV, hệ thống báo chỗ nào chưa phù hợp để nộp.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Xin giúp tôi tạo một script kiểm thử người dùng 15 phút.</span></span></code></pre></div><p>AI có thể xuất:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Script kiểm thử 15 phút:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Trước mời người dùng mô tả trải nghiệm nộp CV gần nhất</span></span>
<span class="line"><span>2. Để người dùng tự hoàn thành upload CV</span></span>
<span class="line"><span>3. Quan sát họ có hiểu được kết quả phản hồi không</span></span>
<span class="line"><span>4. Hỏi: Trong những gợi ý này, cái nào hữu ích nhất, cái nào khiến bạn bối rối</span></span>
<span class="line"><span>5. Hỏi: Nếu lần sau trước khi nộp, bạn có muốn dùng lại không</span></span></code></pre></div><p>Loại output này rất thực dụng, vì nó có thể giúp bạn từ &quot;tôi làm xong nguyên mẫu rồi&quot; bước đến &quot;tôi tiếp theo kiểm thử thế nào&quot;.</p><h3 id="_11-5-đe-ai-đong-vai-nguoi-gac-cong-giai-đoan" tabindex="-1">11.5 Để AI đóng vai &quot;người gác cổng giai đoạn&quot; <a class="header-anchor" href="#_11-5-đe-ai-đong-vai-nguoi-gac-cong-giai-đoan" aria-label="Permalink to “11.5 Để AI đóng vai &quot;người gác cổng giai đoạn&quot;”">​</a></h3><p>Vấn đề phổ biến nhất của mô hình Double Diamond, là người ta sẽ nhảy giai đoạn. Bạn có thể trực tiếp để AI đóng vai người gác cổng, nhắc bạn hiện tại rốt cuộc đang ở bước nào:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Xin đóng vai huấn luyện viên quy trình sản phẩm.</span></span>
<span class="line"><span>Dưới đây là trạng thái dự án hiện tại của tôi: [Mô tả của bạn]</span></span>
<span class="line"><span>Xin đánh giá tôi hiện tại giống đang ở Discover, Define, Develop hay Deliver hơn.</span></span>
<span class="line"><span>Và cho tôi biết:</span></span>
<span class="line"><span>1. Tôi có phải đã nhảy quá sớm sang giai đoạn tiếp theo không</span></span>
<span class="line"><span>2. Hành động đáng bổ sung nhất ở giai đoạn hiện tại là gì</span></span>
<span class="line"><span>3. Những việc nào bây giờ chưa nên làm</span></span></code></pre></div><p>Điều này đặc biệt hữu ích cho người mới, vì bạn rất dễ &quot;chưa nghĩ rõ vấn đề đã bắt đầu vẽ nguyên mẫu&quot;.</p><h2 id="📚-bai-tap" tabindex="-1">📚 Bài tập <a class="header-anchor" href="#📚-bai-tap" aria-label="Permalink to “📚 Bài tập”">​</a></h2><p>Xin bạn dựa vào nội dung bài viết, hoàn thành bài tập sau:</p><ol><li>Chọn một ý tưởng sản phẩm bạn muốn làm gần đây, viết bản nháp 4 bước Discover, Define, Develop, Deliver của nó</li><li>Ở giai đoạn Define, ép mình nén vấn đề thành một câu cụ thể</li><li>Ở giai đoạn Develop, ít nhất liệt kê 3 giải pháp khác nhau, thay vì chỉ chăm chăm vào cách đầu tiên nghĩ ra</li><li>Ở giai đoạn Deliver, viết ra một phiên bản xác minh tối thiểu có thể giao phó trong một tuần</li></ol><h2 id="đoc-them" tabindex="-1">Đọc thêm <a class="header-anchor" href="#đoc-them" aria-label="Permalink to “Đọc thêm”">​</a></h2><p>Bài viết này chủ yếu tham khảo tài liệu chính thức của Design Council về Double Diamond, phù hợp để tiếp tục xem:</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,171))])}}});export{d as __pageData,b as default};
